using Nd30.DocumentEngine.Parsing;using Nd30.SemanticDetector.Detection;using Nd30.LegalValidator.Adapters;using Nd30.LegalValidator.Catalog;using Nd30.LegalValidator.Evaluation;using Nd30.LegalValidator.Model;
namespace Nd30.LegalValidator.Execution;
public sealed record CanonicalRevalidationResult(bool ParserPassed,bool SemanticDetectorPassed,bool LegalValidatorPassed,IReadOnlyList<ValidationResult> Results,IReadOnlyList<string> RemainingFindings,IReadOnlyList<string> RegressionFindings,string? FatalError=null){public bool Completed=>ParserPassed&&SemanticDetectorPassed&&LegalValidatorPassed&&FatalError is null;}
public interface IDocumentRevalidator{CanonicalRevalidationResult Revalidate(string path);}
public sealed class CanonicalDocumentRevalidator:IDocumentRevalidator{readonly RuleCatalog catalog;readonly DateOnly evaluationDate;public CanonicalDocumentRevalidator(string legalRoot,DateOnly? evaluationDate=null){catalog=RuleCatalog.LoadVerifiedRelease(legalRoot);this.evaluationDate=evaluationDate??DateOnly.FromDateTime(DateTime.UtcNow);}public CanonicalRevalidationResult Revalidate(string path){try{var parsed=new DocxParser().Parse(path);if(parsed.Document is null)return new(false,false,false,[],[],[],"The document could not be parsed during revalidation.");var sem=new AdministrativeSemanticDetector().Detect(parsed.Document);var context=SemanticValidationContextBuilder.Build(parsed.Document,sem,evaluationDate);var report=new ValidationEngine(catalog).Validate(context);var remaining=report.Results.Where(x=>x.Status is ValidationStatus.FAIL or ValidationStatus.NEEDS_REVIEW).Select(x=>x.RuleId).Distinct().OrderBy(x=>x).ToList();return new(true,true,true,report.Results,remaining,[]);}catch(Exception){return new(false,false,false,[],[],[],"Canonical document revalidation failed.");}}}
